// Package gen defines the Generator interface and supporting types that
// components implement to produce generated code.
package gen

import (
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"io/fs"
	"maps"
	"path/filepath"
	"slices"
	"sort"
	"strconv"
	"strings"

	"github.com/jsell-rh/stego/internal/types"
)

// Header is the required comment header for all generated files.
const Header = "// Code generated by stego. DO NOT EDIT."

// Generator is the interface that components implement to produce generated
// code. Each component is a Go package that exports a Generator. Alongside
// its files, each generator returns a Wiring struct that the compiler uses
// to assemble shared files (cmd/main.go, go.mod, etc.).
type Generator interface {
	Generate(ctx Context) ([]File, *Wiring, error)
}

// ContextValidator checks resolved component inputs before any generator runs.
// It must not change the context, write files, or render output. Generate must
// use the same checks when called directly. The compiler supplies captured inputs.
type ContextValidator interface {
	ValidateContext(ctx Context) error
}

// GoVersionRequirement declares the minimum Go target for generated code.
// The compiler checks this requirement before it runs any generator.
// Use Go version syntax without the "go" prefix, for example "1.25".
type GoVersionRequirement interface {
	MinimumGoVersion() string
}

// SlotConsumer declares the slot names a generator's output actually
// invokes. The compiler rejects slot bindings that no resolved generator
// consumes: generated code would wire the operator into a constructor but
// never call it, so the bound fills would be silent dead code. A generator
// that consumes no slots must return an empty list.
type SlotConsumer interface {
	ConsumedSlots() []string
}

// RuntimeAuth is what an auth provider states for the verifier of the
// runtime data path (ST-SUP-RP13): the verifier takes the key set of the
// issuer from its discovery document (ST-SUP-RP13-LC21). An empty field is
// not stated. TenantClaim, when set, is the one tenant claim that the
// provider gives, and the declared tenancy claim must be the same.
type RuntimeAuth struct {
	Issuer, Audience, Header, RoleClaim, SubjectClaim, TenantClaim, CAFile string
	Algorithms                                                             []string
}

// RuntimeAuthProvider is an auth provider that the verifier of the runtime
// data path serves through the discovery document of its issuer, such as
// oidc-auth (ST-SUP-RC37). The compiler takes its settings in place of its
// generated code.
type RuntimeAuthProvider interface {
	RuntimeAuth(ctx Context) (RuntimeAuth, error)
}

// DeclaredVariable is one environment variable that a declaration gives a
// component, such as one configuration field of runtime-configuration
// (ST-SUP-RC22-OC09). Its name and its default are fixed text.
type DeclaredVariable struct {
	Name        string
	Type        string
	Required    bool
	Default     *string
	Description string
	Secret      bool
	// Allowed are the allowed values as one text, such as "1 to 10".
	Allowed string
}

// DeclaredVariables are the environment variables of one group of a
// declaration.
type DeclaredVariables struct {
	Group     string
	Variables []DeclaredVariable
}

// VariableDeclarer gives the environment variables that the declaration gives
// a component whose variable names come from its declaration entries, so that
// the platform requirements list them (ST-DLV-INV11). It must check the
// context as Generate does.
type VariableDeclarer interface {
	DeclaredVariables(ctx Context) ([]DeclaredVariables, error)
}

// Probes are the HTTP paths of the liveness and readiness probes that a
// component serves, and the environment variable whose default is the port
// they are served on.
type Probes struct {
	Liveness     string
	Readiness    string
	PortVariable string
}

// ProbeDeclarer gives the probes that a component serves, so that the
// Kubernetes base carries them (ST-DLV-UC07-R03). It must check the context
// as Generate does.
type ProbeDeclarer interface {
	Probes(ctx Context) (Probes, error)
}

// InputFault is a fault of one setting of a component: the setting, by its path under the component's settings,
// such as apis[1].prefix, the value found there, and the fault in a sentence. A generator gives it so that checking
// names the setting and the value, and not only the archetype (walkthrough 9, rank 3).
type InputFault struct {
	// Component is the component whose setting it is.
	Component string
	// Setting is the path of the setting under the component's settings; empty for the settings as a whole.
	Setting string
	// Found is the value found at the setting; empty when the setting is not there.
	Found string
	// Message is the fault in a sentence for a person.
	Message string
}

func (f *InputFault) Error() string { return f.Message }

// InputProvider declares source files before generation. The compiler reads
// each file once and checks its snapshot again before it applies output.
type InputProvider interface {
	InputFiles(config map[string]any) ([]InputFile, error)
}

// Context carries resolved information that generators need to produce code.
type Context struct {
	// Inputs contains compiler-read, project-relative source files.
	Inputs map[string][]byte

	// Conventions from the archetype (layout, error handling, logging, etc.).
	Conventions types.Convention

	// Entities defined in the service declaration.
	Entities []types.Entity

	// Collections from the service declaration.
	Collections []types.Collection

	// SchemaChanges and SchemaHistory are the declaration's changes to the stored shape of its entities after the
	// first release, and the ordered steps that move them (ST-DECL-EN21, ST-DECL-EN22). Entities is the shape after
	// every step; the shape of the first release is Entities with every step undone.
	SchemaChanges []types.SchemaChange
	SchemaHistory []types.SchemaStep

	// SlotBindings from the service declaration, in declaration order.
	// The ordering is significant: generators and the assembler must iterate
	// bindings in the same order to agree on constructor parameter positions.
	SlotBindings []types.SlotDeclaration

	// ModuleName is the Go module path (e.g. "github.com/myorg/user-service").
	// Generators use this to construct full import paths for cross-package
	// references (e.g. importing the slots package from handler code).
	ModuleName string

	// GoVersion is the resolved Go target for generated code.
	GoVersion string

	// SlotsPackage is the relative import path (under ModuleName) for the
	// generated slot operators package (e.g. "internal/slots"). Empty if
	// no slots are configured.
	SlotsPackage string

	// ComponentConfig holds the component-specific config values resolved
	// from defaults and service-level overrides.
	ComponentConfig map[string]any

	// OutputNamespace is the component's declared output namespace
	// (e.g. "internal/api"). Generators can only write files under it.
	OutputNamespace string

	// OutDirName is the name of the output directory relative to the project
	// root (e.g. "out"). Generators use this when constructing full import
	// paths for generated packages within the output directory. With go.mod
	// at the project root, import paths for generated packages must include
	// this prefix (e.g. "<module>/out/internal/slots" instead of
	// "<module>/internal/slots"). Empty string means no prefix is added.
	OutDirName string

	// AuthPackage is the full import path for the auth middleware package
	// (e.g. "github.com/myorg/svc/out/internal/auth"). Generators use this
	// to import auth.IdentityFromContext for extracting caller identity from
	// the request context. Empty if no auth component is resolved.
	AuthPackage string

	// BasePath is prepended to all collection-derived routes (e.g.
	// "/api/hyperfleet/v1"). Empty string means paths are served from root.
	BasePath string

	// ServiceName is the service declaration's name (e.g. "hyperfleet-api").
	// Generators use this to derive error code prefixes and other
	// service-scoped identifiers.
	ServiceName string

	// ErrorTypeBase is an optional URI prefix for RFC 9457 error type URIs
	// (e.g. "https://api.hyperfleet.io/errors/"). When set, error type URIs
	// are constructed as ErrorTypeBase + error-slug. When empty, error types
	// use "about:blank" per RFC 9457.
	ErrorTypeBase string

	// Audit is the audit setting of the service declaration (ST-DECL-EN10), or
	// nil when the declaration omits it, which means audit at level change.
	Audit *types.Audit

	// PortBindings maps each port that the service declaration binds to the
	// component it binds the port to: the overrides whose value is a name.
	PortBindings map[string]string

	// Idempotency is the declaration's idempotency setting (ST-DECL-EN13), or
	// nil when the declaration has none. Generators must not change it.
	Idempotency *types.Idempotency

	// Authorization is the declaration's authorization setting (ST-DECL-EN11),
	// or nil when the declaration binds none. The compiler captures the schema
	// it names into Inputs for the authorization component (ST-SUP-RC29).
	// Generators must not change it.
	Authorization *types.Authorization

	// GoModelSources contains checked provider declarations for field mapping.
	// Each component receives its own copy. Do not change these declarations.
	GoModelSources map[string]GoModelSource

	// PeerNamespaces maps component names to their output namespace paths.
	// Generators use this to construct import paths when they need to
	// reference types defined by other components (e.g. the storage adapter
	// imports the API package's ListOptions/ListResult types to satisfy
	// the Storage interface).
	PeerNamespaces map[string]string

	// PeerConfigs contains resolved declarations for cross-component checks.
	// Generators must not change these maps or their nested values.
	PeerConfigs map[string]map[string]any

	// Observations are the declared observations of the service (ST-DECL-EN20),
	// in declaration order.
	Observations []types.Observation

	// Emitters are the commands, queries, workers, process methods and slot
	// bindings of the declaration whose fills can emit an observation, in
	// declaration order (ST-SUP-RC34-OC03).
	Emitters []Emitter

	// Tenancy is the pooled tenancy of a service that has the tenancy component, and nil for any other service
	// (ST-SUP-RC01-OC40). Generators must not change it.
	Tenancy *Tenancy

	// Commands are the declared commands of the service (ST-DECL-EN18), in declaration order, each with the slot
	// that its fill implements. Generators must not change them.
	Commands []Command

	// Queries are the queries of the declaration (ST-DECL-EN19), in declaration order. Generators must not change
	// them.
	Queries []types.Query

	// Workers are the declared workers of the service (ST-DECL-EN25), in declaration order, each with the slot that
	// its fill implements. Generators must not change them.
	Workers []Worker

	// Subscriptions are the declared subscriptions of the service (ST-DECL-EN28), in declaration order. Generators
	// must not change them.
	Subscriptions []types.Subscription

	// FillSlots gives, for each fill that a command, a query or a worker names and that the project holds, the slot
	// it implements as component.slot, as its fill.yaml states (ST-DECL-INV45). A fill that the project does not hold
	// has no entry.
	FillSlots map[string]string

	// Destinations are the outbox destinations that the components of the service declare in their setting
	// destinations, each with its declared delivery (ST-SUP-RC32-OC12), in the order of the components and of the
	// setting. Generators must not change them.
	Destinations []Destination

	// QueryStreams holds the names of the queries that are served as a server stream: the queries whose gRPC method
	// is a server stream of the proto files of the grpc-application component, which the compiler reads for the check
	// of ST-DECL-INV73 (ST-SUP-RC33-OC08). Generators must not change it.
	QueryStreams map[string]bool

	// ServiceOpenAPI is the OpenAPI document that the rest-api component emits for the service, or with no rest-api
	// the document of the command and query routes that the command component writes (ST-SUP-RC32-OC29). The
	// compiler gives it to the client components go-sdk, cli-application and typescript-sdk when their declaration
	// names no document and no factory, so that each client is generated from the service's own API
	// (ST-SUP-RC06-OC09, ST-SUP-RC04-OC32, ST-SUP-RC24-OC14), and, with no rest-api, to the command component, which
	// writes it. It is nil for every other component.
	ServiceOpenAPI []byte

	// DroppedEntities are the entities that the declaration declares with dropped_by, and DroppedCollections the
	// collections over them (ST-DECL-EN02, ST-GEN-Q47): Entities and Collections do not hold them, so no generator
	// gives them an API, a client, a repository, a handler or a manifest entry, and AtSchemaStep gives them back for
	// the steps before their drop. EntityOrder and CollectionOrder are the names of all entities and collections in
	// the order of the declaration, by which AtSchemaStep puts each one back in its place. Generators must not change
	// them.
	DroppedEntities    []types.Entity
	DroppedCollections []types.Collection
	EntityOrder        []string
	CollectionOrder    []string
}

// AtSchemaStep gives a copy of the context with the stored shape after the first steps steps of the schema
// history: each schema change whose first step is at the position steps or after it is undone, the change whose
// step is last first. AtSchemaStep(0) is the baseline, the shape of the first release, and AtSchemaStep with the
// length of the schema history is the context itself. An add of an entity is undone with the entity and each
// collection over it, an add of a field with the field, a rename by giving the field the column From, with its
// API name kept (StoredNames), and a relax by giving the field what it was before the change
// (types.SchemaChange.RelaxedFrom), a within by taking the within off its reference, a unique of a field by taking
// its unique off the field (types.WithoutUnique), a drop of a field by giving the
// entity back the field of its Definition in its place (DropDefinition), and a drop of an entity by giving back the
// entity and the collections over it, which the declaration keeps with dropped_by (ST-GEN-Q47).
// A seal is undone by giving the field its sensitivity From in its clear column, and for From secret the mark of a
// secret that an older generator stored in clear (types.Field.ClearStored, ST-SUP-RC01-OC49).
// AtSchemaStep refuses a change of another kind, and a change with no step.
func (c Context) AtSchemaStep(steps int) (Context, error) {
	first := map[string]int{}
	for i, step := range c.SchemaHistory {
		if _, seen := first[step.Change]; !seen {
			first[step.Change] = i
		}
	}
	var undo []types.SchemaChange
	for _, change := range c.SchemaChanges {
		at, stepped := first[change.ID]
		if !stepped {
			return Context{}, fmt.Errorf("schema change %q has no step in the schema history", change.ID)
		}
		if change.Kind != "add" && change.Kind != "rename" && change.Kind != "retype" && change.Kind != "require" && change.Kind != "relax" && change.Kind != "within" && change.Kind != "drop" && change.Kind != "seal" && !change.UniqueOfField(c.Entities) {
			return Context{}, fmt.Errorf("schema change %q has the kind %s, which generation does not carry out yet", change.ID, change.Kind)
		}
		if at >= steps {
			undo = append(undo, change)
		}
	}
	if len(undo) == 0 {
		return c, nil
	}
	shaped := c
	shaped.Entities = make([]types.Entity, len(c.Entities))
	for i, entity := range c.Entities {
		entity.Fields = append([]types.Field(nil), entity.Fields...)
		shaped.Entities[i] = entity
	}
	shaped.Collections = append([]types.Collection(nil), c.Collections...)
	sort.SliceStable(undo, func(i, j int) bool { return first[undo[i].ID] > first[undo[j].ID] })
	for _, change := range undo {
		if change.Kind == "drop" && change.Field == "" {
			// A drop of an entity is undone by giving back the entity, as the declaration still declares it with
			// dropped_by, and each collection over it, each in its place (ST-GEN-Q47).
			if err := shaped.restoreEntity(c, change); err != nil {
				return Context{}, err
			}
			continue
		}
		at := -1
		for j, entity := range shaped.Entities {
			if entity.Name == change.Entity {
				at = j
			}
		}
		if at < 0 {
			return Context{}, fmt.Errorf("schema change %q adds to the entity %s, which the declaration does not have", change.ID, change.Entity)
		}
		if change.Kind == "unique" {
			// A unique of a field is undone by taking unique, unique_when_live and its unique_composite group off the
			// field, so its unique index leaves the shape (ST-GEN-INV33, ST-GEN-Q48).
			fields := shaped.Entities[at].Fields
			found := slices.IndexFunc(fields, func(f types.Field) bool { return f.Name == change.Field })
			if found < 0 || (!fields[found].Unique && len(fields[found].UniqueComposite) == 0) {
				return Context{}, fmt.Errorf("schema change %q makes the field %s.%s unique, which the declaration does not declare unique or in a unique_composite", change.ID, change.Entity, change.Field)
			}
			shaped.Entities[at].Fields = types.WithoutUnique(fields, change.Field)
			continue
		}
		if change.Kind == "within" {
			// A within is undone by taking the within off its reference, so the composite key leaves the shape
			// (ST-SUP-RC01-OC46, ST-DECL-Q42).
			ref, ok := shaped.Entities[at].References[change.Field]
			if !ok || ref.WithinField() == "" {
				return Context{}, fmt.Errorf("schema change %q adds the key of the reference %s.%s, which declares no within", change.ID, change.Entity, change.Field)
			}
			references := maps.Clone(shaped.Entities[at].References)
			ref.Within = ""
			references[change.Field] = ref
			shaped.Entities[at].References = references
			continue
		}
		if change.Kind == "drop" {
			// A drop of a field is undone by giving the entity back the field of its Definition, in its place
			// (ST-DECL-EN21, ST-GEN-INV33).
			fields := shaped.Entities[at].Fields
			if slices.ContainsFunc(fields, func(f types.Field) bool { return f.ColumnName() == change.Field || f.Name == change.Field }) {
				return Context{}, fmt.Errorf("schema change %q drops the field %s.%s, which the entity still has", change.ID, change.Entity, change.Field)
			}
			dropped, reason := DropDefinition(change.Definition)
			if reason != "" {
				return Context{}, fmt.Errorf("schema change %q: %s", change.ID, reason)
			}
			dropped.Field.Name = change.Field
			place := 0
			if !dropped.First {
				after := slices.IndexFunc(fields, func(f types.Field) bool { return f.ColumnName() == dropped.After || f.Name == dropped.After })
				if after < 0 {
					return Context{}, fmt.Errorf("schema change %q puts the field %s.%s after %s, which the entity does not have at its step", change.ID, change.Entity, change.Field, dropped.After)
				}
				place = after + 1
			}
			shaped.Entities[at].Fields = slices.Insert(slices.Clone(fields), place, dropped.Field)
			continue
		}
		if change.Kind == "relax" {
			fields := shaped.Entities[at].Fields
			found := slices.IndexFunc(fields, func(f types.Field) bool { return f.ColumnName() == change.Field })
			if found < 0 {
				return Context{}, fmt.Errorf("schema change %q relaxes the column %s.%s, which the declaration does not have", change.ID, change.Entity, change.Field)
			}
			before, reason := change.RelaxedFrom(fields[found])
			if reason != "" {
				return Context{}, fmt.Errorf("schema change %q: %s", change.ID, reason)
			}
			fields[found] = before
			continue
		}
		if change.Kind == "seal" {
			// A seal is undone by giving the field its sensitivity before the change, From, in its clear column; From
			// public is the same field as no From (types.Field.Public) (ST-SUP-RC01-OC49, ST-DECL-INV102).
			fields := shaped.Entities[at].Fields
			found := slices.IndexFunc(fields, func(f types.Field) bool { return f.Name == change.Field })
			if found < 0 {
				return Context{}, fmt.Errorf("schema change %q seals the field %s.%s, which the declaration does not have", change.ID, change.Entity, change.Field)
			}
			fields[found].Sensitivity, fields[found].CompareOnly = change.From, false
			// A field that its declaration named secret and that a generator before postgres-adapter 6.13.0 stored
			// in clear: its stored shape is the field in clear, with its CHECKs and no search index (walkthrough 13,
			// W13-B1).
			fields[found].ClearStored = change.From == "secret"
			fields[found].Column, fields[found].SealedFrom = "", ""
			continue
		}
		if change.Kind == "rename" {
			// A rename is undone by giving the field its column before the change; its API name stays.
			fields := shaped.Entities[at].Fields
			found := slices.IndexFunc(fields, func(f types.Field) bool { return f.ColumnName() == change.Field })
			if found < 0 {
				return Context{}, fmt.Errorf("schema change %q renames the column %s.%s, which the declaration does not have", change.ID, change.Entity, change.Field)
			}
			fields[found].Column = change.From
			if fields[found].Column == fields[found].Name {
				fields[found].Column = ""
			}
			continue
		}
		if change.Kind == "retype" {
			// A retype is undone by giving the field its type and constraints before the change, in the column before
			// it: the column of the retype before it on the field, or the field's name (StoredNames).
			fields := shaped.Entities[at].Fields
			found := slices.IndexFunc(fields, func(f types.Field) bool { return f.Name == change.Field })
			if found < 0 {
				return Context{}, fmt.Errorf("schema change %q retypes the field %s.%s, which the declaration does not have", change.ID, change.Entity, change.Field)
			}
			before := RetypeField(change)
			before.Name, before.Optional, before.Sensitivity = fields[found].Name, fields[found].Optional, fields[found].Sensitivity
			if change.Definition == "" {
				before.Default = nil
			}
			before.Column = ""
			for _, earlier := range c.SchemaChanges {
				if earlier.Kind == "retype" && earlier.Entity == change.Entity && earlier.Field == change.Field && first[earlier.ID] < first[change.ID] {
					before.Column = RetypeColumn(change.Field, types.FieldType(change.From))
				}
			}
			fields[found] = before
			continue
		}
		if change.Field == "" {
			shaped.Entities = append(shaped.Entities[:at:at], shaped.Entities[at+1:]...)
			var kept []types.Collection
			for _, collection := range shaped.Collections {
				if collection.Entity != change.Entity {
					kept = append(kept, collection)
				}
			}
			shaped.Collections = kept
			continue
		}
		fields := shaped.Entities[at].Fields
		found := -1
		for j, field := range fields {
			if field.Name == change.Field {
				found = j
			}
		}
		if found < 0 {
			return Context{}, fmt.Errorf("schema change %q adds the field %s.%s, which the declaration does not have", change.ID, change.Entity, change.Field)
		}
		shaped.Entities[at].Fields = append(fields[:found:found], fields[found+1:]...)
	}
	return shaped, nil
}

// restoreEntity gives the context back the entity that the drop change removes, from the dropped entities of c, with
// each collection over it, each in its place in the order of the declaration.
func (shaped *Context) restoreEntity(c Context, change types.SchemaChange) error {
	at := slices.IndexFunc(c.DroppedEntities, func(e types.Entity) bool { return e.Name == change.Entity && e.DroppedBy == change.ID })
	if at < 0 {
		return fmt.Errorf("schema change %q drops the entity %s, which the declaration does not declare with dropped_by: %s", change.ID, change.Entity, change.ID)
	}
	if slices.ContainsFunc(shaped.Entities, func(e types.Entity) bool { return e.Name == change.Entity }) {
		return fmt.Errorf("schema change %q drops the entity %s, which the declaration still has", change.ID, change.Entity)
	}
	entity := c.DroppedEntities[at]
	entity.DroppedBy = ""
	entity.Fields = append([]types.Field(nil), entity.Fields...)
	shaped.Entities = insertInOrder(shaped.Entities, entity, c.EntityOrder, func(e types.Entity) string { return e.Name })
	for _, collection := range c.DroppedCollections {
		if collection.Entity == change.Entity {
			shaped.Collections = insertInOrder(shaped.Collections, collection, c.CollectionOrder, func(c types.Collection) string { return c.Name })
		}
	}
	return nil
}

// insertInOrder inserts item into list before the first item that comes after it in order, by name.
func insertInOrder[T any](list []T, item T, order []string, name func(T) string) []T {
	rank := func(n string) int {
		if i := slices.Index(order, n); i >= 0 {
			return i
		}
		return len(order)
	}
	at := slices.IndexFunc(list, func(other T) bool { return rank(name(other)) > rank(name(item)) })
	if at < 0 {
		at = len(list)
	}
	return slices.Insert(slices.Clone(list), at, item)
}

// StoredNames gives a copy of the entities in which each field that a schema change of kind rename names has the
// API name of the field before its first rename and the column of its declared name (ST-GEN-UC12-R04): a rename
// does not rename the field in the API, so every generator of an API, a client or a fill reads Name, and the
// generators of the tables and the statements read ColumnName. A chain of renames on one entity, From of one being
// Field of an earlier one, gives the first From. The patchable fields of a collection name a renamed field by its
// declared name too, and StoredCollections gives them its API name. It refuses a rename of a field that something
// else names, by the declared name, because those names are not mapped yet: a reference field, a unique_composite,
// an invariant, the scope, implicit fields or upsert key of a collection, the context fields or the generation fields
// of the entity.
func StoredNames(entities []types.Entity, invariants []types.DeclaredInvariant, collections []types.Collection, changes []types.SchemaChange) ([]types.Entity, error) {
	renamed := renames(changes)
	retyped := map[[2]string]bool{}
	for _, change := range changes {
		if change.Kind == "retype" {
			retyped[[2]string{change.Entity, change.Field}] = true
		}
	}
	if len(renamed) == 0 && len(retyped) == 0 {
		return entities, nil
	}
	out := make([]types.Entity, len(entities))
	for i, entity := range entities {
		entity.Fields = append([]types.Field(nil), entity.Fields...)
		for j, field := range entity.Fields {
			from, ok := renamed[[2]string{entity.Name, field.Name}]
			if retyped[[2]string{entity.Name, field.Name}] {
				// A retyped field keeps its API name and is stored in the column <field>_<type> of its type after its
				// last retype (decision on ST-GEN-Q23 (a), orchestrator under the owner's delegation, 2026-11-14).
				if ok {
					return nil, fmt.Errorf("the entity %s: generation does not rename and retype the field %s both yet", entity.Name, field.Name)
				}
				if reason := namedElsewhere(entity, field.Name, invariants, collections, true); reason != "" {
					return nil, fmt.Errorf("the entity %s: generation does not retype the field %s yet, because %s names it by its declared name; STEGO does not map that name to the column yet", entity.Name, field.Name, reason)
				}
				column := RetypeColumn(field.Name, field.Type)
				if slices.ContainsFunc(entities[i].Fields, func(f types.Field) bool { return f.Name == column || f.Column == column }) {
					return nil, fmt.Errorf("the entity %s declares a field %s, which is the column of the retyped field %s; give the field another name", entity.Name, column, field.Name)
				}
				entity.Fields[j].Column = column
				continue
			}
			if !ok {
				continue
			}
			from = firstName(renamed, entity.Name, from)
			if reason := namedElsewhere(entity, field.Name, invariants, collections, false); reason != "" {
				return nil, fmt.Errorf("the entity %s: generation does not rename the field %s yet, because %s names it by its declared name; STEGO does not map that name to the column yet", entity.Name, field.Name, reason)
			}
			if slices.ContainsFunc(entities[i].Fields, func(f types.Field) bool { return f.Name == from }) {
				return nil, fmt.Errorf("the entity %s declares a field %s, which is the API name of the renamed field %s; give the new field another name", entity.Name, from, field.Name)
			}
			entity.Fields[j].Name, entity.Fields[j].Column = from, field.Name
		}
		out[i] = entity
	}
	return out, nil
}

// StoredCollections gives a copy of the collections in which each patchable field that a schema change of kind
// rename names has its API name, the From of its first rename, as StoredNames gives the field (ST-GEN-UC12-R04): the
// declaration names the field by its declared name, and every generator reads the API name, so the patch request
// keeps the name of the release before.
func StoredCollections(collections []types.Collection, changes []types.SchemaChange) []types.Collection {
	renamed := renames(changes)
	if len(renamed) == 0 || len(collections) == 0 {
		return collections
	}
	out := slices.Clone(collections)
	for i, collection := range out {
		if len(collection.Patchable) == 0 {
			continue
		}
		patchable := slices.Clone(collection.Patchable)
		for j, field := range patchable {
			if from, ok := renamed[[2]string{collection.Entity, field}]; ok {
				patchable[j] = firstName(renamed, collection.Entity, from)
			}
		}
		out[i].Patchable = patchable
	}
	return out
}

// renames gives the From of each schema change of kind rename, by its entity and its Field.
func renames(changes []types.SchemaChange) map[[2]string]string {
	renamed := map[[2]string]string{}
	for _, change := range changes {
		if change.Kind == "rename" {
			renamed[[2]string{change.Entity, change.Field}] = change.From
		}
	}
	return renamed
}

// firstName follows a chain of renames on the entity back from the name from, the From of a rename, to the From of
// the first rename: the API name of the field. The number of steps is limited, so a cycle cannot loop.
func firstName(renamed map[[2]string]string, entity, from string) string {
	for steps := 0; steps <= len(renamed); steps++ {
		earlier, again := renamed[[2]string{entity, from}]
		if !again {
			break
		}
		from = earlier
	}
	return from
}

// SealColumn gives the sealed column of a field that a seal moves out of the clear column column: <column>_sealed,
// cut as the other generated names are cut, as RetypeColumn cuts it (ST-SUP-RC01-OC49).
func SealColumn(column string) string {
	name := column + "_sealed"
	if len(name) <= 63 {
		return name
	}
	sum := sha256.Sum256([]byte(name))
	return name[:46] + "_" + hex.EncodeToString(sum[:8])
}

// SealedNames gives a copy of the entities in which each field that a schema change of kind seal names is stored in
// its sealed column (SealColumn), with its clear column in SealedFrom while the history gives the change no contract
// step: from its expand step to its contract step a release writes both columns (ST-SUP-RC01-OC49,
// ST-SUP-RP10-LC49). No other schema change names a sealed field (ST-DECL-INV102), so its clear column is its name.
func SealedNames(entities []types.Entity, changes []types.SchemaChange, history []types.SchemaStep) []types.Entity {
	contracted := map[string]bool{}
	for _, step := range history {
		if step.Phase == "contract" {
			contracted[step.Change] = true
		}
	}
	sealed := map[[2]string]string{}
	for _, change := range changes {
		if change.Kind == "seal" {
			sealed[[2]string{change.Entity, change.Field}] = change.ID
		}
	}
	if len(sealed) == 0 {
		return entities
	}
	out := make([]types.Entity, len(entities))
	for i, entity := range entities {
		entity.Fields = append([]types.Field(nil), entity.Fields...)
		for j, field := range entity.Fields {
			id, ok := sealed[[2]string{entity.Name, field.Name}]
			if !ok {
				continue
			}
			clear := field.ColumnName()
			entity.Fields[j].Column = SealColumn(clear)
			if !contracted[id] {
				entity.Fields[j].SealedFrom, entity.Fields[j].SealChange = clear, id
			}
		}
		out[i] = entity
	}
	return out
}

// DefinitionField reads the Definition of a retyped field, as [name:] type[, item]..., such as integer, min 0, into a
// field (decision on ST-GEN-Q07 (a)). It takes the items of DropDefinition but the place of the field, which a retype
// does not move, and gives a reason when the Definition cannot be read.
func DefinitionField(definition string) (types.Field, string) {
	dropped, reason := readDefinition(definition, false)
	return dropped.Field, reason
}

// DroppedField is a field that a drop removes, as the Definition of the drop gives it (ST-DECL-EN21): the field, and
// its place in the entity, after the field After, or First.
type DroppedField struct {
	Field types.Field
	After string
	First bool
}

// DropDefinition reads the Definition of a dropped field (ST-DECL-EN21, ST-DECL-INV62): the type, then one item for
// each attribute that the field had, separated by commas: min_length N, max_length N, min N, max N, values V1 V2 ...,
// default D, optional, unique, pii or secret, after F or first, and last pattern P, because a pattern can hold a
// comma. An item that the Definition does not name the field did not have. It gives a reason, and no field, when the
// Definition cannot be read, names an item twice, or gives no place.
func DropDefinition(definition string) (DroppedField, string) {
	dropped, reason := readDefinition(definition, true)
	if reason == "" && dropped.After == "" && !dropped.First {
		return DroppedField{}, "the definition gives no place of the field; end it with after F, the field that it came after, or first"
	}
	return dropped, reason
}

// readDefinition reads a Definition; place tells whether it may give the place of the field.
func readDefinition(definition string, place bool) (DroppedField, string) {
	parts := strings.Split(definition, ",")
	head := strings.TrimSpace(parts[0])
	if _, typ, named := strings.Cut(head, ":"); named {
		head = strings.TrimSpace(typ)
	}
	out := DroppedField{Field: types.Field{Type: types.FieldType(head)}}
	field := &out.Field
	if !types.ValidFieldTypes[field.Type] {
		return out, fmt.Sprintf("the type %q is not a field type", head)
	}
	seen := map[string]bool{}
	for i, part := range parts[1:] {
		key, value, _ := strings.Cut(strings.TrimSpace(part), " ")
		value = strings.TrimSpace(value)
		item := key
		if key == "pii" || key == "secret" {
			item = "sensitivity"
		}
		if key == "after" || key == "first" {
			item = "place"
		}
		if seen[item] {
			return out, fmt.Sprintf("the definition gives %s twice", item)
		}
		seen[item] = true
		if key == "pattern" {
			// A pattern can hold a comma, as in {1,9}, so it is the last item and takes the rest of the text.
			_, rest, _ := strings.Cut(strings.Join(parts[i+1:], ","), "pattern")
			field.Pattern = strings.TrimSpace(rest)
			break
		}
		number, err := strconv.ParseFloat(value, 64)
		switch key {
		case "min_length", "max_length":
			length, err := strconv.Atoi(value)
			if err != nil {
				return out, fmt.Sprintf("the constraint %s %q is not a whole number", key, value)
			}
			if key == "min_length" {
				field.MinLength = &length
			} else {
				field.MaxLength = &length
			}
		case "min", "max":
			if err != nil {
				return out, fmt.Sprintf("the constraint %s %q is not a number", key, value)
			}
			if key == "min" {
				field.Min = &number
			} else {
				field.Max = &number
			}
		case "default":
			// The field keeps its default, so the field before a retype or a drop keeps the DEFAULT of its column
			// (ST-DECL-INV62, ST-GEN-INV33).
			if value == "" {
				return out, "the constraint default has no value"
			}
			field.Default = definitionDefault(field.Type, value)
		case "values":
			field.Values = strings.Fields(value)
			if len(field.Values) == 0 {
				return out, "the item values names no value"
			}
			if field.Type != types.FieldTypeEnum {
				return out, "the item values is only for an enum"
			}
		case "optional", "unique", "pii", "secret", "first":
			if value != "" {
				return out, fmt.Sprintf("the item %s takes no value, and the definition gives %q", key, value)
			}
			switch key {
			case "optional":
				field.Optional = true
			case "unique":
				field.Unique = true
			case "first":
				out.First = true
			default:
				field.Sensitivity = key
			}
		case "after":
			if value == "" || strings.Contains(value, " ") {
				return out, fmt.Sprintf("the item after needs one field name, and the definition gives %q", value)
			}
			out.After = value
		default:
			return out, fmt.Sprintf("the constraint %q is not one a field has", key)
		}
		if item == "place" && !place {
			return out, "a retype keeps the place of its field, so its definition takes no after and no first"
		}
	}
	if field.Type == types.FieldTypeEnum && len(field.Values) == 0 && place {
		return out, "the definition of an enum needs its values, as values V1 V2 ..."
	}
	return out, ""
}

// definitionDefault reads the value of the default item of a Definition as the declaration's YAML gives a default of
// the field type typ: a whole number as int and a number with a fraction as float64 for a number field, true or
// false for a bool field, and a string for every other field, without the quotes that it can have.
func definitionDefault(typ types.FieldType, value string) any {
	switch typ {
	case types.FieldTypeInt32, types.FieldTypeInt64, types.FieldTypeFloat, types.FieldTypeDouble, types.FieldTypeMoney:
		if number, err := strconv.Atoi(value); err == nil {
			return number
		}
		if number, err := strconv.ParseFloat(value, 64); err == nil {
			return number
		}
	case types.FieldTypeBool:
		if truth, err := strconv.ParseBool(value); err == nil {
			return truth
		}
	}
	if unquoted, err := strconv.Unquote(value); err == nil && strings.HasPrefix(value, `"`) {
		return unquoted
	}
	if len(value) >= 2 && value[0] == '\'' && value[len(value)-1] == '\'' {
		return value[1 : len(value)-1]
	}
	return value
}

// RetypeColumn gives the column of a field after a retype to the type typ: <field>_<type>, cut as the other
// generated names are cut, to its first 46 bytes and 16 hexadecimal digits of the sha256 digest of the whole name
// when it is longer than 63 bytes (decision on ST-GEN-Q23 (a), orchestrator under the owner's delegation, 2026-11-14).
func RetypeColumn(field string, typ types.FieldType) string {
	name := field + "_" + string(typ)
	if len(name) <= 63 {
		return name
	}
	sum := sha256.Sum256([]byte(name))
	return name[:46] + "_" + hex.EncodeToString(sum[:8])
}

// RetypeField gives the field before a retype: the field of its Definition when it has one, else a field of the type
// From with no constraint (decision on ST-GEN-Q07 (a), orchestrator under the owner's delegation, 2026-11-13).
func RetypeField(change types.SchemaChange) types.Field {
	if change.Definition != "" {
		if field, reason := DefinitionField(change.Definition); reason == "" {
			field.Name = change.Field
			return field
		}
	}
	return types.Field{Name: change.Field, Type: types.FieldType(change.From)}
}

// namedElsewhere tells what, other than the field itself, names the field of the entity, or empty. patchable tells
// whether the patchable fields of a collection count: StoredCollections maps them for a rename.
func namedElsewhere(entity types.Entity, field string, invariants []types.DeclaredInvariant, collections []types.Collection, patchable bool) string {
	if _, ok := entity.References[field]; ok {
		return "a reference"
	}
	for _, f := range entity.Fields {
		if f.Type == types.FieldTypeRef && f.Name == field {
			return "a reference"
		}
		if slices.Contains(f.UniqueComposite, field) || (f.Name == field && len(f.UniqueComposite) > 0) {
			return "a unique_composite"
		}
	}
	if slices.Contains(entity.ContextFields, field) || slices.Contains(entity.GenerationFields, field) {
		return "a context or generation field of the entity"
	}
	for _, invariant := range invariants {
		if invariant.On == entity.Name && (slices.Contains(invariant.By, field) || strings.Contains(invariant.Where, field)) {
			return "the invariant " + invariant.Name
		}
	}
	for _, collection := range collections {
		if collection.Entity != entity.Name {
			continue
		}
		_, scope := collection.Scope[field]
		_, implicit := collection.Implicit[field]
		if scope || implicit || slices.Contains(collection.UpsertKey, field) || (patchable && slices.Contains(collection.Patchable, field)) {
			return "the collection " + collection.Name
		}
	}
	return ""
}

// Destination is one outbox destination that a component declares in its setting destinations: its name, the
// component, and whether its messages must land and whether the destination is idempotent, nil when the setting
// leaves the property out (ST-SUP-RC32-OC12).
type Destination struct {
	Name, Component      string
	MustLand, Idempotent *bool
}

// Command is one declared command (ST-DECL-EN18) with what the compiler read of its fill.
type Command struct {
	types.Command
	// FillSlot is the slot that the command's one fill implements, as component.slot, as its fill.yaml names it,
	// or empty when the project holds no such fill.
	FillSlot string
}

// Worker is one declared worker with what the compiler read of its fill.
type Worker struct {
	types.Worker
	// FillSlot is the slot that the worker's one fill implements, as component.slot, as its fill.yaml names it, or
	// empty when the project holds no such fill.
	FillSlot string
}

// EmitterKind tells how the generated code gives an emitter's fill its probe.
type EmitterKind string

// The emitter kinds. A command, query, worker or process method gets its
// probe through its handle or its input; a slot binding gets it through the
// context that its slot's component passes the fill (ST-SUP-RC34-OC04).
const (
	EmitterCommand       EmitterKind = "command"
	EmitterQuery         EmitterKind = "query"
	EmitterWorker        EmitterKind = "worker"
	EmitterProcessMethod EmitterKind = "process method"
	EmitterSlotBinding   EmitterKind = "slot binding"
)

// OpenAPIProvider is a generator that emits the OpenAPI document of the service: the rest-api component. The
// compiler gives the document to the client components that name no document of their own (ServiceOpenAPI).
type OpenAPIProvider interface {
	OpenAPIDocument(ctx Context) ([]byte, error)
}

// RouteOpenAPIProvider is a generator that makes the OpenAPI document of the command and query routes of a service
// with no rest-api component from the context of the command component: the rest-api generator. The command
// component writes the document, and the compiler gives it to the client components that name no document of their
// own (ST-SUP-RC32-OC29). It gives nil when the service serves no command and no get or list query over HTTP.
type RouteOpenAPIProvider interface {
	RouteOpenAPIDocument(command Context) ([]byte, error)
}

// Emitter is one command, query, worker, process method or slot binding.
// Name is its declared name, and collection.slot for a slot binding.
type Emitter struct {
	Name string
	Kind EmitterKind
}

// Tenancy is what the generators of a pooled service read of its tenancy (ST-DECL-EN09).
type Tenancy struct {
	// Key is the name of the tenant column of each owned table: tenancy.key, or tenant_id when it is omitted.
	Key string
	// Provisioning is the declared tenant provisioning (ST-DECL-EN27), or nil when the declaration states none.
	Provisioning *types.TenantProvisioning
}

// TenancyComponent is the name of the tenancy component (ST-SUP-RC27).
const TenancyComponent = "tenancy"

// File represents a single generated output file.
type File struct {
	// Path is relative to the project output root (e.g. "internal/api/handler.go").
	Path string

	// Content is the file body, excluding the generated header.
	Content []byte
}

// Bytes returns the complete file content ready to be written to disk.
// For Go source files, it prepends the required generated-file
// header using Go comment syntax. For non-Go files (JSON, YAML, etc.), the
// content is returned as-is because Go-comment syntax would make them
// unparseable by their format's standard tooling.
func (f File) Bytes() []byte {
	ext := filepath.Ext(f.Path)
	if ext == ".go" {
		return []byte(Header + "\n\n" + string(f.Content))
	}
	return f.Content
}

// Wiring captures what a component needs wired into shared generated files
// (e.g. cmd/main.go, go.mod). Every constructor index must identify an entry
// in Constructors, including metadata for an unused constructor. At most one
// component can declare primary MiddlewareConstructor wiring.
type Wiring struct {
	// Imports lists Go import paths the component needs in main.go.
	Imports []string

	// Constructors lists constructor call expressions for main.go assembly.
	// Each entry is a code fragment like "api.NewUserHandler(userService, ...)".
	// The derived value name must not be predeclared in Go. String expressions
	// cannot distinguish a shadowed language name from an intended dependency.
	Constructors []string

	// ConstructorResources appends compiler-owned arguments to a constructor.
	// Resources use explicit types instead of local variable name conventions.
	ConstructorResources map[int][]Resource

	// ConstructorReturnsError marks constructors that return (value, error).
	// Startup stops on an error. Cleanup for earlier constructors still runs.
	ConstructorReturnsError map[int]bool

	// BackgroundTasks lists constructor indexes that run until cancellation.
	// Each value must have a Run(context.Context) error method. Run must stop
	// when its context is canceled. The service waits for all tasks before
	// resource cleanup. A task that stops before cancellation fails the service.
	BackgroundTasks []int

	// ConstructorCollections maps constructor index to the collection name
	// it handles. The assembler uses this to inject slot operators into the
	// correct handler constructors, replacing convention-based name matching
	// (e.g. inferring collection from "New<Collection>Handler" naming convention).
	// Only handler constructors that should receive slot operator injection
	// need entries here; non-handler constructors are simply omitted.
	ConstructorCollections map[int]string

	// Routes lists route registration expressions for main.go assembly.
	// Each entry is a code fragment like "mux.Handle(\"/users\", userHandler)".
	Routes []string

	// MiddlewareConstructor, if non-nil, indicates which constructor index
	// produces an auth middleware. The assembler uses this to wrap the mux
	// with the middleware, replacing fragile string matching on constructor
	// expressions (e.g. checking for "AuthMiddleware" substring).
	MiddlewareConstructor *int

	// MiddlewareWrapExpr is a format string that produces the expression
	// to wrap the HTTP handler with middleware. It must contain exactly two
	// %s verbs: the first is replaced with the middleware variable name
	// (after disambiguation), the second with the handler variable
	// (typically "mux").
	// Example: "%s(%s)" for function-type middleware → "authMiddleware(mux)".
	// Example: "%s.Handler(%s)" for struct-type middleware → "authMiddleware.Handler(mux)".
	// Required when MiddlewareConstructor is non-nil.
	MiddlewareWrapExpr string

	// NeedsDB indicates whether this component requires a database connection.
	// The assembler uses this to determine whether to emit database setup code
	// in main.go, replacing fragile string matching on constructor expressions.
	// The database is a *sql.DB of database/sql with the pgx driver.
	NeedsDB bool

	// DatabaseAccess names the existing objects for the common installer.
	// The compiler rejects duplicate ownership and unsafe permission sets.
	DatabaseAccess []DatabaseObject

	// BackupObjects names database objects that a backup of the application
	// database must include so a restore stays usable. The compiler merges
	// these into one operator manifest next to the access manifest. The
	// empty set means the component has no database objects of its own.
	BackupObjects []BackupObject

	// VerifyDatabaseAccess requires a separate runtime role before startup.
	// The component must also declare its database objects and database use.
	VerifyDatabaseAccess bool

	// GoModRequires lists module dependencies for the generated go.mod.
	// Keys are module paths (e.g. "github.com/jackc/pgx/v5"), values are
	// version strings (e.g. "v5.11.0"). The assembler collects these from all
	// component wirings and emits a require block.
	GoModRequires map[string]string

	// ConstructorDeps maps constructor index to the list of variable names
	// (from other wirings' constructors) that this constructor references in
	// its expression. The assembler uses this to topologically sort constructor
	// declarations so that referenced variables are declared before referencing
	// ones. Variable names here correspond to the raw variable name derived
	// from the target constructor's expression via rawConstructorVarName
	// (e.g. "queue" for outbox.NewQueue(db)).
	ConstructorDeps map[int][]string

	// PostDBCalls lists Go expressions that should be called after database
	// setup and before constructor declarations in the generated main.go.
	// Each expression must return an error (e.g. "storage.Migrate(db)").
	// The assembler wraps each call in error handling:
	//   if err := <expr>; err != nil { return err }
	PostDBCalls []string

	// Middlewares lists additional middleware constructors that wrap the
	// HTTP handler (mux). Each entry references a constructor index and
	// provides a wrap expression. These are applied in order: first entry
	// wraps mux directly (innermost), last entry wraps outermost. The
	// primary MiddlewareConstructor (auth) is always applied outermost
	// of all, after these.
	Middlewares []MiddlewareSpec

	// ConstructorDeferCalls maps constructor index to a method call
	// expression that should be deferred after the constructor variable is
	// declared. For example, {0: "Stop()"} causes the assembler to emit
	// `defer jwtHandler.Stop()` after `jwtHandler := auth.NewJWTHandler()`.
	// The assembler prepends the disambiguated variable name and a dot.
	ConstructorDeferCalls map[int]string

	// ConstructorStages maps the index of a constructor that returns an
	// error to a call of a function of the constructor's package,
	// func(error) string, on the error err, that names the stage of a
	// refused start, such as "stegoruntime.StartStage(err)". When it gives a
	// stage, main reports that stage in place of the constructor's own; the
	// failure record still holds no error text (ST-SUP-RP14-LC05).
	ConstructorStages map[int]string

	// ModeSelection selects a generated function with signature
	// func() ([]string, error) that gives the modes the process runs. The
	// assembler calls it first in run, at the stage modes, before the
	// database and every constructor, so a refused mode stops the start at
	// its own stage, and the failure record of a later failure names the
	// selected modes (ST-GEN-INV26, ST-GEN-INV16). Only one component can
	// supply it.
	ModeSelection *ModeSelectionSpec

	// OuterMiddlewares lists middleware constructors that wrap the HTTP
	// handler OUTSIDE the auth middleware layer. These are the outermost
	// middleware in the chain — they run first on every request, before
	// auth and before any Middlewares entries. Use this for cross-cutting
	// concerns like CORS that must process requests before authentication.
	// The wrapping order is: OuterMiddlewares(auth(Middlewares(mux))).
	OuterMiddlewares []MiddlewareSpec

	// HTTPErrorLogger selects the constructor that provides HTTPErrorLog() *log.Logger.
	// The assembler uses this logger for HTTP server diagnostics. Only one
	// component can provide it. The constructor is consumed when HTTP routes exist.
	HTTPErrorLogger *int

	// DatabaseOpener selects a generated function with signature
	// func(string) (*sql.DB, error). The argument is the resolved database URL.
	// The process reads DATABASE_URL or DATABASE_URL_FILE before this call. The
	// generated main owns the returned pool. Only one component can supply it.
	// Any consumed database resource uses this factory, including consumers
	// that do not use a constructor from the factory's component.
	DatabaseOpener *DatabaseOpenerSpec

	// MigrationJob selects a generated function with signature
	// func(context.Context) error that main.go runs in place of the service
	// when the process is started with the one argument migrate, the
	// migration job of the runtime library (tenant.MigrationJob). Only one
	// component can supply it.
	MigrationJob *MigrationJobSpec

	// SchemaCheck selects a generated function with signature
	// func(context.Context, *sql.DB) error that main.go runs after the
	// database ping and before the access check, at the stage that the
	// function Stage of the same package gives for its error (ST-SUP-RC02-OC57).
	SchemaCheck *SchemaCheckSpec

	// DiscoveryRoutes lists route registration expressions for main.go
	// assembly that must be registered OUTSIDE the auth middleware chain.
	// These are unauthenticated documentation/discovery endpoints (e.g.
	// OpenAPI spec, metadata). The assembler registers them on the top-level
	// handler so they bypass auth, validation, and other inner middleware.
	// Each entry is a code fragment like
	// "topMux.HandleFunc(\"GET /openapi\", discoveryHandler.ServeOpenAPI)".
	DiscoveryRoutes []string

	// StdlibImports lists standard library packages that must be imported
	// in main.go for this component's constructor expressions or wiring to
	// work. For example, a component whose constructor expression uses
	// os.Getenv() should list "os". The assembler adds these to the stdlib
	// import block and seeds their aliases into the disambiguation maps.
	StdlibImports []string
}

// DatabaseOpenerSpec names a generated SQL pool factory.
type DatabaseOpenerSpec struct {
	Namespace string
	Function  string
}

// MigrationJobSpec names the generated function of the migration job and,
// when Stage is set, a generated function with signature func(error) string
// in the same package that gives the stage of a failure, which the failure
// record names in place of migrate. The stage holds no error text.
type MigrationJobSpec struct {
	Namespace string
	Function  string
	Stage     string
}

// SchemaCheckSpec names the generated schema check and the function with
// signature func(error) string that gives the stage of its failure, both in
// the package of the import path Namespace.
type SchemaCheckSpec struct {
	Namespace string
	Function  string
	Stage     string
}

// ModeSelectionSpec names the function of a generated package, in the
// import path Namespace, that gives the modes the process runs.
type ModeSelectionSpec struct {
	Namespace string
	Function  string
}

// MiddlewareSpec describes a middleware constructor and how it wraps the
// HTTP handler.
type MiddlewareSpec struct {
	// ConstructorIndex is the index into Constructors for this middleware.
	ConstructorIndex int

	// WrapExpr is a format string with two %s verbs: the first is replaced
	// with the middleware variable name (after disambiguation), the second
	// with the handler variable to wrap.
	WrapExpr string
}

// ValidateNamespace checks that every file path in files is under the given
// namespace prefix. Namespace is a slash-separated relative path
// (e.g. "internal/api"). Returns an error listing all violations.
func ValidateNamespace(namespace string, files []File) error {
	if err := ValidatePath(namespace); err != nil {
		return fmt.Errorf("invalid output namespace: %w", err)
	}

	prefix := namespace + "/"

	var violations []string
	for _, f := range files {
		// The path must either equal the namespace (a file named exactly the
		// namespace, unlikely but valid) or start with namespace + "/".
		if ValidatePath(f.Path) != nil || (f.Path != namespace && !strings.HasPrefix(f.Path, prefix)) {
			violations = append(violations, f.Path)
		}
	}

	if len(violations) > 0 {
		return &NamespaceError{
			Namespace:  namespace,
			Violations: violations,
		}
	}
	return nil
}

// ValidatePath requires one canonical path below an output root. Do not clean
// paths before this check: cleaning can hide an attempted traversal.
func ValidatePath(name string) error {
	invalid := name == "." || !fs.ValidPath(name) || strings.ContainsAny(name, "\\:<>\"|?*") || !filepath.IsLocal(name)
	for _, r := range name {
		invalid = invalid || r < 32 || r == 127
	}
	for _, part := range strings.Split(name, "/") {
		invalid = invalid || strings.HasSuffix(part, ".") || strings.HasSuffix(part, " ")
		base := strings.ToUpper(strings.SplitN(part, ".", 2)[0])
		invalid = invalid || base == "CON" || base == "PRN" || base == "AUX" || base == "NUL"
		if len(base) == 4 && (strings.HasPrefix(base, "COM") || strings.HasPrefix(base, "LPT")) {
			invalid = invalid || (base[3] >= '1' && base[3] <= '9')
		}
	}
	if invalid {
		return fmt.Errorf("path %q must be a canonical relative path without traversal", name)
	}
	return nil
}

// NamespaceError reports files that fall outside a component's declared
// output namespace.
type NamespaceError struct {
	Namespace  string
	Violations []string
}

func (e *NamespaceError) Error() string {
	return fmt.Sprintf("files outside namespace %q: %s",
		e.Namespace, strings.Join(e.Violations, ", "))
}

// Resource identifies a value supplied by the service runtime.
type Resource string

const ServiceContext Resource = "service-context"
const SQLDatabase Resource = "sql-database"

// OptionalSQLDatabase supplies the process pool, or nil when no consumed
// constructor requires a database. It does not create a database dependency.
const OptionalSQLDatabase Resource = "optional-sql-database"
